CREATE TABLE kups_groups (id TEXT PRIMARY KEY, name TEXT NOT NULL, opening_amount INTEGER, start_date TEXT, version INTEGER NOT NULL DEFAULT 1, closed_through TEXT, created_at TEXT NOT NULL);
INSERT INTO kups_groups(id,name,created_at) VALUES('dayun-rimba-sejahtera','KUPS Rimba Sejahtera · Dayun',strftime('%Y-%m-%dT%H:%M:%SZ','now'));
CREATE TABLE kups_members (group_id TEXT NOT NULL REFERENCES kups_groups(id), email TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('viewer','treasurer')), disabled INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(group_id,email));
CREATE TABLE kups_transactions (id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES kups_groups(id), date TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('income','expense')), category TEXT NOT NULL, description TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0 AND amount<=1000000000000), quantity REAL, unit TEXT, unit_price INTEGER, object_id TEXT, evidence_id TEXT, source_ref TEXT, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE INDEX kups_transactions_group_date ON kups_transactions(group_id,date);
CREATE TABLE kups_evidence (id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES kups_groups(id), filename TEXT NOT NULL, type TEXT NOT NULL, size INTEGER NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE kups_audit (id TEXT PRIMARY KEY, group_id TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, snapshot TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE kups_periods (group_id TEXT NOT NULL, month TEXT NOT NULL, counted_amount INTEGER, note TEXT NOT NULL DEFAULT '', closed_by TEXT, closed_at TEXT, PRIMARY KEY(group_id,month));
CREATE TRIGGER kups_tx_insert_lock BEFORE INSERT ON kups_transactions WHEN NEW.date<(SELECT start_date FROM kups_groups WHERE id=NEW.group_id) OR substr(NEW.date,1,7)<=COALESCE((SELECT closed_through FROM kups_groups WHERE id=NEW.group_id),'') BEGIN SELECT RAISE(ABORT,'KUPS_PERIOD_LOCKED'); END;
CREATE TRIGGER kups_tx_update_lock BEFORE UPDATE ON kups_transactions WHEN NEW.group_id!=OLD.group_id OR NEW.date<(SELECT start_date FROM kups_groups WHERE id=NEW.group_id) OR substr(NEW.date,1,7)<=COALESCE((SELECT closed_through FROM kups_groups WHERE id=NEW.group_id),'') OR substr(OLD.date,1,7)<=COALESCE((SELECT closed_through FROM kups_groups WHERE id=OLD.group_id),'') BEGIN SELECT RAISE(ABORT,'KUPS_PERIOD_LOCKED'); END;

CREATE UNIQUE INDEX kups_source_unique ON kups_transactions(group_id,source_ref) WHERE source_ref!='';
